.t20-bracket-legs-rr,.t20-bracket-legs-riskusd,.t20-bracket-legs-rwdusd{color:var(--bl-txt);font-variant-numeric:tabular-nums}
.t20-bracket-legs-pop{animation:t20-bracket-legs-pop .32s ease}
@keyframes t20-bracket-legs-pop{0%{transform:scale(1)}40%{transform:scale(1.16)}100%{transform:scale(1)}}
