js:
var P='.t20-bracket-legs-';
var q=function(s){return root.querySelector(P+s);};
var rgStop=q('range--stop'),rgTgt=q('range--tgt');
var pinS=q('pin--stop'),pinE=q('pin--entry'),pinT=q('pin--tgt');
var fRisk=q('fill--risk'),fRwd=q('fill--rwd');
var labS=q('lab--stop'),labE=q('lab--entry'),labT=q('lab--tgt');
var sval=q('sval'),tval=q('tval'),rrEl=q('rr'),riskEl=q('riskusd'),rwdEl=q('rwdusd');
var lastEl=q('last');
var entry=5812.25,mult=50,qty=2,last=5812.25;
var f2=function(n){return n.toFixed(2);};
var usd=function(n){return '$'+Math.round(n).toLocaleString('en-US');};
function render(pop){
  var s=parseFloat(rgStop.value),t=parseFloat(rgTgt.value);
  var span=s+t,L=9,R=91;
  var ep=L+(R-L)*(s/span);
  pinS.style.left=L+'%';pinE.style.left=ep+'%';pinT.style.left=R+'%';
  fRisk.style.left=L+'%';fRisk.style.width=(ep-L)+'%';
  fRwd.style.left=ep+'%';fRwd.style.width=(R-ep)+'%';
  labS.textContent=f2(entry-s);labE.textContent='ENTRY '+f2(entry);labT.textContent=f2(entry+t);
  sval.textContent='-'+f2(s);tval.textContent='+'+f2(t);
  rrEl.textContent=(t/s).toFixed(2);
  riskEl.textContent=usd(s*mult*qty);rwdEl.textContent=usd(t*mult*qty);
  if(pop){rrEl.classList.remove('t20-bracket-legs-pop');void rrEl.offsetWidth;rrEl.classList.add('t20-bracket-legs-pop');}
}
rgStop.addEventListener('input',function(){render(true);});
rgTgt.addEventListener('input',function(){render(true);});
render(false);
setInterval(function(){
  var d=(Math.random()<.5?-1:1)*(Math.round(Math.random()*3)*0.25);
  if(d===0)d=0.25;
  last=Math.round((last+d)*4)/4;
  lastEl.textContent=f2(last);
  lastEl.classList.remove('t20-bracket-legs-is-up','t20-bracket-legs-is-dn');
  void lastEl.offsetWidth;
  lastEl.classList.add(d>0?'t20-bracket-legs-is-up':'t20-bracket-legs-is-dn');
},1600);

