@keyframes t20-oco-pair-run{0%{top:2%}50%{top:88%}100%{top:2%}}
@keyframes t20-oco-pair-glowup{0%{box-shadow:0 0 0 0 rgba(55,217,154,.5)}100%{box-shadow:0 0 0 9px rgba(55,217,154,0)}}
@keyframes t20-oco-pair-glowdn{0%{box-shadow:0 0 0 0 rgba(255,92,122,.5)}100%{box-shadow:0 0 0 9px rgba(255,92,122,0)}}
