js:
var P='.t20-oco-pair-';
var legUp=root.querySelector(P+'leg--up'),legDn=root.querySelector(P+'leg--dn');
var state=root.querySelector(P+'state'),pulse=root.querySelector(P+'pulse');
var bUp=root.querySelector(P+'btn--up'),bDn=root.querySelector(P+'btn--dn'),bRs=root.querySelector(P+'btn--rs');
var badge=function(el){return el.querySelector(P+'badge');};
function reset(){
  [legUp,legDn].forEach(function(l){
    l.classList.remove('t20-oco-pair-is-fill','t20-oco-pair-is-cxl');
    badge(l).textContent='WORKING';
  });
  state.textContent='ARMED';state.style.color='#8FB6FF';
  pulse.style.display='';
}
function fire(win,lose,txt,col){
  win.classList.add('t20-oco-pair-is-fill');win.classList.remove('t20-oco-pair-is-cxl');
  badge(win).textContent='FILLED';
  pulse.style.display='none';
  state.textContent=txt;state.style.color=col;
  setTimeout(function(){
    lose.classList.add('t20-oco-pair-is-cxl');lose.classList.remove('t20-oco-pair-is-fill');
    badge(lose).textContent='CANCELLED';
  },380);
}
bUp.addEventListener('click',function(){fire(legUp,legDn,'TARGET HIT +$956','#37D99A');});
bDn.addEventListener('click',function(){fire(legDn,legUp,'STOP HIT -$704','#FF5C7A');});
bRs.addEventListener('click',reset);

