.t20-trail-dial{--td-line:#1D2533;--td-txt:#E7ECF6;--td-dim:#7A87A0;--td-up:#37D99A;--td-dn:#FF5C7A;box-sizing:border-box;width:100%;max-width:320px;padding:9px 11px;background:radial-gradient(120% 120% at 18% 0%,#151C2B,#0B0F17);border:1px solid var(--td-line);border-radius:12px;color:var(--td-txt);font-family:ui-sans-serif,-apple-system,"SF Pro Text",Segoe UI,Roboto,sans-serif;font-size:11px;line-height:1.15;font-variant-numeric:tabular-nums}
.t20-trail-dial-head{display:flex;align-items:center;gap:6px;margin-bottom:6px}
.t20-trail-dial-tag{font-size:8.5px;letter-spacing:.09em;color:#FFC48F;background:rgba(255,160,80,.13);border:1px solid rgba(255,160,80,.28);border-radius:4px;padding:2px 4px}
.t20-trail-dial-sym{font-weight:700}
.t20-trail-dial-qty{margin-left:auto;font-size:9px;color:var(--td-dim);font-variant-numeric:tabular-nums}
.t20-trail-dial-body{display:flex;gap:12px;align-items:center}
.t20-trail-dial-knob{position:relative;width:88px;height:88px;flex:none;border-radius:50%;cursor:grab;touch-action:none;outline:none}
.t20-trail-dial-knob:active{cursor:grabbing}
.t20-trail-dial-knob:focus-visible{box-shadow:0 0 0 3px rgba(143,182,255,.55)}
.t20-trail-dial-svg{width:88px;height:88px;display:block;transform:rotate(135deg)}
.t20-trail-dial-ring{fill:none;stroke:#1C2433;stroke-width:8;stroke-linecap:round;stroke-dasharray:197.9 263.9}
.t20-trail-dial-arc{fill:none;stroke:#FFA850;stroke-width:8;stroke-linecap:round;stroke-dasharray:66 263.9;filter:drop-shadow(0 0 4px rgba(255,168,80,.5));transition:stroke-dasharray .3s cubic-bezier(.22,1.3,.4,1)}
.t20-trail-dial-hand{position:absolute;left:0;top:0;right:0;bottom:0;transform:rotate(-45deg);transition:transform .3s cubic-bezier(.22,1.3,.4,1)}
