var P='.t20-trail-dial-';
var knob=root.querySelector(P+'knob'),arc=root.querySelector(P+'arc'),hand=root.querySelector(P+'hand');
var num=root.querySelector(P+'num'),lastEl=root.querySelector(P+'last'),peakEl=root.querySelector(P+'peak');
var stopEl=root.querySelector(P+'stop'),cval=root.querySelector(P+'cval'),bar=root.querySelector(P+'barfill');
var trail=1.20,last=62418,peak=62905,stop=peak*(1-trail/100);
var fmt=function(n){return Math.round(n).toLocaleString('en-US');};
function paint(){
  var frac=(trail-0.2)/2.8;
  arc.style.strokeDasharray=(197.9*frac).toFixed(1)+' 263.9';
  hand.style.transform='rotate('+(-135+270*frac).toFixed(1)+'deg)';
  num.textContent=trail.toFixed(2);
  knob.setAttribute('aria-valuenow',trail.toFixed(2));
  knob.setAttribute('aria-valuetext',trail.toFixed(2)+' percent');
  lastEl.textContent=fmt(last);peakEl.textContent=fmt(peak);stopEl.textContent=fmt(stop);
  var cush=last-stop,room=peak*trail/100;
  cval.textContent=(cush>=0?'+':'-')+fmt(Math.abs(cush));
  cval.style.color=cush>=0?'#37D99A':'#FF5C7A';
  bar.style.width=Math.max(2,Math.min(100,cush/room*100)).toFixed(0)+'%';
}
function setTrail(v){trail=Math.max(0.2,Math.min(3,Math.round(v*20)/20));stop=Math.max(stop,peak*(1-trail/100));paint();}
function fromPoint(e){
  var r=knob.getBoundingClientRect();
  var a=Math.atan2(e.clientX-(r.left+r.width/2),(r.top+r.height/2)-e.clientY)*180/Math.PI;
  if(a>135)a=135;if(a<-135)a=-135;
  setTrail(0.2+2.8*((a+135)/270));
}
knob.addEventListener('pointerdown',function(e){knob.setPointerCapture(e.pointerId);fromPoint(e);e.preventDefault();});
knob.addEventListener('pointermove',function(e){if(e.buttons)fromPoint(e);});
knob.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='ArrowUp'||k==='ArrowRight'){setTrail(trail+0.05);e.preventDefault();}
  else if(k==='ArrowDown'||k==='ArrowLeft'){setTrail(trail-0.05);e.preventDefault();}
  else if(k==='Home'){setTrail(0.2);e.preventDefault();}
  else if(k==='End'){setTrail(3);e.preventDefault();}
});
paint();
setInterval(function(){
  last=Math.round(last+(Math.random()-0.46)*130);
  if(last>peak){peak=last;var ns=peak*(1-trail/100);
    if(ns>stop){stop=ns;stopEl.classList.remove('t20-trail-dial-ratchet');void stopEl.offsetWidth;stopEl.classList.add('t20-trail-dial-ratchet');}}
  if(last<=stop){last=stop;paint();setTimeout(function(){last=peak=Math.round(stop+400);stop=peak*(1-trail/100);paint();},900);}
  paint();
},1100);

