var P='.t20-iceberg-split-';
var fill=root.querySelector(P+'visfill'),lab=root.querySelector(P+'vislab'),wrap=root.querySelector(P+'blocks');
var hidEl=root.querySelector(P+'hid'),filEl=root.querySelector(P+'fil'),refEl=root.querySelector(P+'ref');
var rng=root.querySelector(P+'range'),dsp=root.querySelector(P+'dsp');
var TOTAL=25000,N=12,blocks=[],disp=2500,done=0,left=TOTAL,clip=2500,timer=null;
var fmt=function(n){return Math.round(n).toLocaleString('en-US');};
for(var i=0;i<N;i++){var b=document.createElement('span');b.className='t20-iceberg-split-blk t20-iceberg-split-live';wrap.appendChild(b);blocks.push(b);}
function paint(){
  var hidden=Math.max(0,left-clip);
  var lit=Math.ceil(N*hidden/TOTAL);
  blocks.forEach(function(b,i){b.classList.toggle('t20-iceberg-split-gone',i>=lit);});
  hidEl.textContent=fmt(hidden);filEl.textContent=fmt(done);
  refEl.textContent=Math.max(0,Math.ceil(hidden/disp));
  lab.textContent='shown '+fmt(clip);
  fill.style.width=(clip/disp*100).toFixed(1)+'%';
}
function reset(){
  disp=parseInt(rng.value,10);dsp.textContent=fmt(disp);
  done=0;left=TOTAL;clip=Math.min(disp,left);
  fill.classList.remove('t20-iceberg-split-refill');paint();
}
function step(){
  if(left<=0){reset();return;}
  var take=Math.min(clip,Math.max(disp*0.08,Math.round(disp*(0.08+Math.random()*0.22)/25)*25));
  clip-=take;done+=take;left-=take;
  paint();
  if(clip<=0&&left>0){
    var top=blocks.filter(function(b){return !b.classList.contains('t20-iceberg-split-gone');}).pop();
    if(top){top.classList.remove('t20-iceberg-split-surface');void top.offsetWidth;top.classList.add('t20-iceberg-split-surface');}
    setTimeout(function(){
      clip=Math.min(disp,left);
      fill.classList.add('t20-iceberg-split-refill');paint();
      setTimeout(function(){fill.classList.remove('t20-iceberg-split-refill');},520);
    },330);
  }
}
rng.addEventListener('input',reset);
reset();
timer=setInterval(step,620);

