js:
var P='.t20-twap-sched-';
var bars=root.querySelector(P+'bars'),sweep=root.querySelector(P+'sweep'),clock=root.querySelector(P+'clock');
var doneEl=root.querySelector(P+'done'),avgEl=root.querySelector(P+'avg'),slip=root.querySelector(P+'slip');
var t1=root.querySelector(P+'t1'),sl=root.querySelector(P+'slices'),part=root.querySelector(P+'part');
var chips=root.querySelectorAll(P+'chip');
var TOTAL=40000,ARR=227.42,n=12,i=0,filled=0,notional=0,timer=null,mins=30,sec=84;
var fmt=function(v){return Math.round(v).toLocaleString('en-US');};
function build(m){
  mins=m;n=m===15?10:(m===30?12:16);
  bars.innerHTML='';
  for(var k=0;k<n;k++){
    var s=document.createElement('span');s.className='t20-twap-sched-slot';
    var f=document.createElement('i');f.className='t20-twap-sched-fill';
    s.appendChild(f);bars.appendChild(s);
  }
  var end=new Date(1970,0,1,9,30+m,0);
  t1.textContent=('0'+end.getHours()).slice(-2)+':'+('0'+end.getMinutes()).slice(-2);
  sl.textContent=n+' slices · '+(m/n).toFixed(1).replace('.0','')+'m';
  i=0;filled=0;notional=0;sec=0;
  doneEl.textContent='0';avgEl.textContent=ARR.toFixed(2);
  slip.textContent='▲ 0.0 bp';slip.classList.remove('t20-twap-sched-bad');
  sweep.style.left='0%';
}
function tick(){
  var slots=bars.children;
  if(i>=n){setTimeout(function(){build(mins);},1400);return;}
  var s=slots[i],f=s.querySelector(P+'fill');
  if(i>0){slots[i-1].classList.add('t20-twap-sched-done');slots[i-1].classList.remove('t20-twap-sched-now');}
  s.classList.add('t20-twap-sched-now');
  var h=62+Math.random()*38;
  f.style.height=h.toFixed(0)+'%';
  var qty=TOTAL/n;var px=ARR+(Math.random()-0.56)*0.14;
  filled+=qty;notional+=qty*px;i++;
  doneEl.textContent=fmt(filled);
  var avg=notional/filled;avgEl.textContent=avg.toFixed(2);
  var bp=(avg-ARR)/ARR*10000;
  slip.textContent=(bp<=0?'▼ ':'▲ +')+bp.toFixed(1)+' bp';
  slip.classList.toggle('t20-twap-sched-bad',bp>0);
  sweep.style.left=(i/n*100).toFixed(2)+'%';
  part.textContent='participation '+(6+Math.random()*4).toFixed(1)+'%';
}
function run(){clearInterval(timer);timer=setInterval(function(){sec+=Math.round(mins*60/n);var t=9*3600+30*60+sec;clock.textContent=('0'+Math.floor(t/3600)).slice(-2)+':'+('0'+Math.floor(t/60)%60).slice(-2)+':'+('0'+t%60).slice(-2);tick();},900);}
Array.prototype.forEach.call(chips,function(c){
  c.addEventListener('click',function(){
    Array.prototype.forEach.call(chips,function(x){x.classList.remove('t20-twap-sched-on');});
    c.classList.add('t20-twap-sched-on');
    build(parseInt(c.getAttribute('data-t20-min'),10));run();
  });
});
build(30);run();

