var P='.t20-basket-send-';
var wrap=root.querySelector(P+'rows'),gval=root.querySelector(P+'gval'),nval=root.querySelector(P+'nval');
var dir=root.querySelector(P+'dir'),cnt=root.querySelector(P+'cnt'),go=root.querySelector(P+'go');
var legs=[
 {s:'NVDA',b:1,q:1200,p:178.84},
 {s:'AAPL',b:1,q:900,p:227.42},
 {s:'MSFT',b:0,q:400,p:431.20},
 {s:'AMD',b:1,q:2500,p:160.92}];
var els=[],busy=false;
var k=function(v){return '$'+(Math.abs(v)/1000).toFixed(0)+'k';};
legs.forEach(function(l,i){
  l.on=true;l.n=l.q*l.p;
  var b=document.createElement('button');b.type='button';b.className='t20-basket-send-row';
  b.setAttribute('aria-pressed','true');
  b.innerHTML='<span class="t20-basket-send-sym">'+l.s+'</span>'+
   '<span class="t20-basket-send-sd t20-basket-send-sd--'+(l.b?'b':'s')+'">'+(l.b?'B':'S')+'</span>'+
   '<span class="t20-basket-send-qty">'+l.q.toLocaleString('en-US')+'</span>'+
   '<span class="t20-basket-send-not">'+(l.b?'+':'-')+k(l.n)+'</span>'+
   '<span class="t20-basket-send-wrap"><i class="t20-basket-send-w t20-basket-send-w--'+(l.b?'b':'s')+'"></i></span>'+
   '<span class="t20-basket-send-tick">OK</span>';
  wrap.appendChild(b);els.push(b);
  b.addEventListener('click',function(){
    if(busy)return;
    l.on=!l.on;b.classList.toggle('t20-basket-send-off',!l.on);
    b.setAttribute('aria-pressed',l.on?'true':'false');
    totals();
  });
});
function count(el,from,to,fmt){
  var t0=null,d=420,live=true;
  function step(ts){if(!live)return;if(!t0)t0=ts;var p=Math.min(1,(ts-t0)/d);var e=1-Math.pow(1-p,3);
    el.textContent=fmt(from+(to-from)*e);if(p<1)requestAnimationFrame(step);}
  requestAnimationFrame(step);
  setTimeout(function(){live=false;el.textContent=fmt(to);},d+70);
}
var pg=0,pn=0;
