  var g=0,net=0,mx=0,live=0;
  legs.forEach(function(l){if(l.on){g+=l.n;net+=l.b?l.n:-l.n;live++;if(l.n>mx)mx=l.n;}});
  legs.forEach(function(l,i){
    els[i].querySelector(P+'w').style.width=(l.on&&mx?Math.max(8,l.n/mx*100):0)+'%';
  });
  cnt.textContent=live+' legs';
  count(gval,pg,g,function(v){return k(v);});
  count(nval,pn,net,function(v){return (v>=0?'+':'-')+k(v);});
  pg=g;pn=net;
  var up=net>=0;
  nval.style.color=up?'#37D99A':'#FF5C7A';
  dir.style.color=up?'#37D99A':'#FF5C7A';
  dir.textContent=up?'▲ long':'▼ short';
