js:
var P='.t20-quickpad-fire-';
var pad=root.querySelector(P+'pad'),num=root.querySelector(P+'num'),usd=root.querySelector(P+'usd');
var px=root.querySelector(P+'px'),msg=root.querySelector(P+'msg');
var keys=['1','2','3','4','5','6','7','8','9','.','0','DEL'],map={},buf='0.35',mark=62418.50;
keys.forEach(function(k){
  var b=document.createElement('button');b.type='button';
  b.className='t20-quickpad-fire-key'+(k==='DEL'?' t20-quickpad-fire-key--fn':'');
  b.textContent=k==='DEL'?'⌫':k;
  b.setAttribute('aria-label',k==='DEL'?'delete':k);
  pad.appendChild(b);map[k]=b;
  b.addEventListener('click',function(e){press(k,b);});
});
function paint(){
  num.textContent=buf===''?'0':buf;
  var q=parseFloat(buf||'0')||0;
  usd.textContent='$'+Math.round(q*mark).toLocaleString('en-US');
}
function ripple(b){
  var r=document.createElement('i');r.className='t20-quickpad-fire-rip';
  b.appendChild(r);setTimeout(function(){r.remove();},460);
}
function press(k,b){
  b.classList.add('t20-quickpad-fire-down');ripple(b);
  setTimeout(function(){b.classList.remove('t20-quickpad-fire-down');},120);
  if(k==='DEL')buf=buf.slice(0,-1);
  else if(k==='.'){if(buf.indexOf('.')<0)buf=(buf===''?'0':buf)+'.';}
  else{if(buf==='0')buf='';if(buf.replace('.','').length<6)buf+=k;}
  paint();
}
root.addEventListener('keydown',function(e){
  var k=e.key;
  if(k==='Backspace'){press('DEL',map.DEL);e.preventDefault();}
  else if(map[k]){press(k,map[k]);e.preventDefault();}
});
function fire(side){
  var q=parseFloat(buf||'0')||0;
  msg.textContent=(side>0?'▲ BOUGHT ':'▼ SOLD ')+q.toFixed(2)+' @ '+mark.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  msg.style.color=side>0?'#37D99A':'#FF5C7A';
  msg.classList.remove('t20-quickpad-fire-flash');void msg.offsetWidth;msg.classList.add('t20-quickpad-fire-flash');
}
root.querySelector(P+'act--buy').addEventListener('click',function(){fire(1);});
root.querySelector(P+'act--sell').addEventListener('click',function(){fire(-1);});
paint();
setInterval(function(){
  var d=(Math.random()-0.5)*38;mark=Math.round((mark+d)*2)/2;
  px.textContent=mark.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});
  px.classList.remove('t20-quickpad-fire-up','t20-quickpad-fire-dn');void px.offsetWidth;
  px.classList.add(d>0?'t20-quickpad-fire-up':'t20-quickpad-fire-dn');
  paint();
},1400);

