js:
var P='.t20-hotkey-desk-';
var caps=root.querySelector(P+'caps'),log=root.querySelector(P+'log');
var posEl=root.querySelector(P+'pos'),avgEl=root.querySelector(P+'avg'),plEl=root.querySelector(P+'pl');
var defs=[{k:'b',l:'B',m:'b'},{k:'s',l:'S',m:'s'},{k:'f',l:'F',m:'f'},{k:'1',l:'1',m:'x'},{k:'2',l:'2',m:'x'},{k:'3',l:'3',m:'x'},{k:'escape',l:'ESC',m:'x'}];
var map={},size=1,pos=0,avg=0,mark=20418.25,t=0;
var px=function(n){return n.toLocaleString('en-US',{minimumFractionDigits:2,maximumFractionDigits:2});};
defs.forEach(function(d){
  var b=document.createElement('button');b.type='button';
  b.className='t20-hotkey-desk-cap t20-hotkey-desk-cap--'+d.m;
  b.textContent=d.l;b.setAttribute('aria-label','hotkey '+d.l);
  caps.appendChild(b);map[d.k]=b;
  b.addEventListener('click',function(){act(d.k);});
});
function stamp(){t+=1+Math.floor(Math.random()*4);var s=9*3600+31*60+t;
  return ('0'+Math.floor(s/3600)).slice(-2)+':'+('0'+Math.floor(s/60)%60).slice(-2)+':'+('0'+s%60).slice(-2);}
function push(msg,kind){
  var d=document.createElement('div');d.className='t20-hotkey-desk-line t20-hotkey-desk-line--'+kind;
  d.innerHTML='<span class="t20-hotkey-desk-ts">'+stamp()+'</span><span class="t20-hotkey-desk-msg">'+msg+'</span>';
  log.insertBefore(d,log.firstChild);
  while(log.children.length>4)log.removeChild(log.lastChild);
}
function stats(){
  posEl.textContent=pos===0?'FLAT':(pos>0?'+':'')+pos;
  posEl.style.color=pos===0?'#E7ECF6':(pos>0?'#37D99A':'#FF5C7A');
  avgEl.textContent=pos===0?'--':px(avg);
  var pl=pos===0?0:(mark-avg)*pos*20;
  plEl.textContent='P/L '+(pl>0?'▲ +$':(pl<0?'▼ -$':'$'))+Math.abs(Math.round(pl)).toLocaleString('en-US');
  plEl.style.color=pl>0?'#37D99A':(pl<0?'#FF5C7A':'#7A87A0');
}
function act(k){
  var b=map[k];
  if(b){b.classList.add('t20-hotkey-desk-hit');setTimeout(function(){b.classList.remove('t20-hotkey-desk-hit');},130);}
  mark=Math.round((mark+(Math.random()-0.5)*6)*4)/4;
  if(k==='b'||k==='s'){
    var q=k==='b'?size:-size;
    var np=pos+q;
    if(pos===0||pos*q>0)avg=(avg*Math.abs(pos)+mark*Math.abs(q))/Math.abs(np||1);
    pos=np;
    push((k==='b'?'▲ BUY ':'▼ SELL ')+size+' @ '+px(mark),k==='b'?'up':'dn');
  }else if(k==='f'){
    if(pos!==0){push('■ FLATTEN '+Math.abs(pos)+' @ '+px(mark),'n');pos=0;avg=0;}
    else push('■ already flat','n');
  }else if(k==='escape'){push('✕ cancel all working','n');}
  else{size=parseInt(k,10);push('size preset → '+size+' lot'+(size>1?'s':''),'n');}
  stats();
}
root.addEventListener('keydown',function(e){
  var k=e.key.toLowerCase();
  if(map[k]){act(k);e.preventDefault();}
});
push('desk armed · hotkeys live','n');
push('size preset → 1 lot','n');
push('▲ BUY 1 @ 20,412.75','up');
pos=1;avg=20412.75;
stats();
